qss:
QWidget { background: #071718; color: #e8fffb; font-family: "Segoe UI", "Inter", sans-serif; font-size: 10pt; }
QMainWindow, QDialog { background: #071718; }
QLabel { background: transparent; }
QFrame#Sidebar, QFrame#HeaderBar, QFrame#ComposerFrame, QFrame#ChatSurface { background: #0d2425; border: 1px solid #2f625f; border-radius: 16px; }
QLabel#TitleLabel { font-size: 16pt; font-weight: 700; color: #e8fffb; }
QLabel#SubtleLabel { color: #91c8c1; }
QPushButton { background: #173b3a; color: #e8fffb; border: 1px solid #2f625f; border-radius: 12px; padding: 8px 12px; }
QPushButton:hover { background: #1e4c4a; }
QPushButton#AccentButton { background: #28c7a2; border: 1px solid #4cdbbc; color: #ffffff; font-weight: 700; }
QPushButton#AccentButton:hover { background: #4cdbbc; }
QPushButton#DangerButton { background: #4b2a46; }
QComboBox, QLineEdit, QPlainTextEdit, QTextEdit, QListWidget, QTextBrowser, QSpinBox { background: #061112; color: #e8fffb; border: 1px solid #2f625f; border-radius: 12px; padding: 8px; }
QListWidget::item { border-radius: 10px; padding: 8px; margin: 2px; }
QListWidget::item:selected { background: #174945; border: 1px solid #28c7a2; }
QScrollArea { border: none; background: transparent; }
QScrollBar:vertical { background: #0d2425; width: 16px; margin: 2px; border-radius: 6px; }
QScrollBar::handle:vertical { background: #2f625f; min-height: 32px; border-radius: 7px; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: transparent; }
QProgressBar { border: 1px solid #2f625f; border-radius: 10px; background: #061112; text-align: center; min-height: 18px; }
QProgressBar::chunk { background: #28c7a2; border-radius: 8px; }
QFrame#AssistantBubbleCard { background: #0d2425; border: 1px solid #2f625f; border-left: 4px solid #4cdbbc; border-radius: 16px; }
QFrame#UserBubbleCard { background: #174945; border: 1px solid #2f625f; border-radius: 16px; }
